public class DeadlockFix{static final Object A=new Object(),B=new Object();static void work(Object x,Object y){synchronized(x){synchronized(y){System.out.println(Thread.currentThread().getName()+" completed");}}}public static void main(String[]z)throws Exception{Thread t1=new Thread(()->work(A,B)),t2=new Thread(()->work(A,B));t1.start();t2.start();t1.join();t2.join();System.out.println("Consistent lock order avoids deadlock");}}
